import sqlite3
import sys


def setup(con):
    pass


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else ":memory:"
    con = sqlite3.connect(path)
    setup(con)
    while True:
        line = input("> ")
        if line == "quit":
            break


if __name__ == "__main__":
    main()
